import React, { useState, useEffect } from 'react';
import axios from 'axios';

// 🟢 App.js එකෙන් එවන දත්ත
export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  
  // Content Manager Form State
  const [formTitle, setFormTitle] = useState('');
  const [formGrade, setFormGrade] = useState('Grade 10');
  const [formType, setFormType] = useState('PDF');
  const [formFilePath, setFormFilePath] = useState('');

  const fullSubject = subject || 'Not Set';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 6 to 11';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [isEditing, setIsEditing] = useState(false);
  const [profileData, setProfileData] = useState({ 
      name: userName || '', username: userUsername || '', qualifications: qualifications || '',
      email: email || '', phone: phone || '', address: address || '' 
  });

  // Database එකෙන් Materials සහ Timetable දත්ත ලබාගැනීම
  const fetchData = () => {
    axios.get('http://localhost:8081/api/learning-materials')
      .then(res => setMaterials(res.data))
      .catch(err => console.log(err));

    axios.get('http://localhost:8081/api/timetable')
      .then(res => {
        // මේ ලොග් වුණු ගුරුවරයාට අදාළ පන්ති පමණක් පෙරලා ගනී
        const myClasses = res.data.filter(c => c.teacher === userName);
        setTimetable(myClasses);
      })
      .catch(err => console.log(err));
  };

  useEffect(() => {
    fetchData();
    setProfileData({ 
        name: userName || '', username: userUsername || '', qualifications: qualifications || 'B.Sc. / Diploma (Please Update)',
        email: email || '', phone: phone || '', address: address || '' 
    });
  }, [userName, userUsername, qualifications, email, phone, address]);

  // පාඩම් ද්‍රව්‍ය Database එකට එකතු කිරීම
  const handlePublishLesson = (e) => {
    e.preventDefault();
    const payload = {
      title: formTitle,
      material_type: formType,
      file_path: formFilePath,
      grade: formGrade,
      subject: teachingSubject,
      teacher_name: userName
    };

    axios.post('http://localhost:8081/api/add-material', payload)
      .then(res => {
        if (res.data.status === "Success") {
          alert("✅ Lesson Material Published Successfully!");
          fetchData();
          setFormTitle('');
          setFormFilePath('');
        } else {
          alert("❌ Upload Failed!");
        }
      }).catch(() => alert("Server Error!"));
  };

  // පාඩම් ද්‍රව්‍ය Database එකෙන් ඉවත් කිරීම
  const handleDeleteMaterial = (id) => {
    if (window.confirm("Are you sure you want to delete this material?")) {
      axios.delete(`http://localhost:8081/api/delete-material/${id}`).then(() => fetchData());
    }
  };

  const handleProfileUpdate = () => { alert("✅ Profile details updated successfully!"); setIsEditing(false); };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, {profileData.name || 'Teacher'}! 👋</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Your Content Management System is active. Manage your classes and students below.</p>
              </div>
              <div style={{ position: 'absolute', right: '-10px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>👨‍🏫</div>
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grades" count={teachingGrade} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Total Students" count="145" icon="🧑‍🎓" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Total Uploaded Content" count={materials.length} icon="📝" color="#fefce8" textColor="#eab308" />
            </div>

            <h2 style={{ color: '#1e293b', margin: '0 0 15px 0', fontSize: '20px' }}>🏫 My Teaching Classes (Timetable)</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px', marginBottom: '30px' }}>
                {timetable.length > 0 ? timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #3b82f6` }}>
                    <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{c.grade}</div>
                    <h3 style={{ margin: '0 0 10px 0', color: '#1e293b', fontSize: '18px' }}>{c.subject}</h3>
                    <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 15px 0' }}>🕒 {c.day}, {c.time_slot}</p>
                    <button onClick={() => setActiveTab('upload')} style={classBtnStyle}>📂 Manage Content</button>
                  </div>
                )) : (
                  <p style={{ color: '#64748b', fontSize: '14px' }}>No classes scheduled on the timetable for you yet.</p>
                )}
            </div>
          </div>
        );

      case 'upload':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
                <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                    <div>
                      <label style={labelStyle}>Lesson Title</label>
                      <input type="text" placeholder="e.g. Introduction to Algebra" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={inputStyle} />
                    </div>
                    <div style={{ display: 'flex', gap: '20px' }}>
                      <div style={{ flex: 1 }}>
                        <label style={labelStyle}>Grade Category</label>
                        <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={inputStyle}>
                          <option value="Grade 9">Grade 9</option>
                          <option value="Grade 10">Grade 10</option>
                          <option value="Grade 11">Grade 11</option>
                        </select>
                      </div>
                      <div style={{ flex: 1 }}>
                        <label style={labelStyle}>Material Type</label>
                        <select value={formType} onChange={e => setFormType(e.target.value)} style={inputStyle}>
                          <option value="PDF">PDF Handout</option>
                          <option value="Video">Video Lesson</option>
                        </select>
                      </div>
                    </div>
                    <div>
                      <label style={labelStyle}>File Path / YouTube Video URL</label>
                      <input type="text" placeholder="e.g. uploads/lesson1.pdf or https://youtube.com/..." value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={inputStyle} />
                    </div>
                    <button type="submit" style={{ padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px', fontSize: '14px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' }}>+ Publish Lesson</button>
                </form>
            </div>

            {/* Uploaded Materials View Box */}
            <h3 style={{ color: '#1e293b', marginBottom: '15px', fontSize: '18px' }}>📝 Managed Materials List</h3>
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
                    <th style={{ padding: '12px 10px' }}>Title</th>
                    <th style={{ padding: '12px 10px' }}>Type</th>
                    <th style={{ padding: '12px 10px' }}>Grade</th>
                    <th style={{ padding: '12px 10px' }}>Location / Link</th>
                    <th style={{ padding: '12px 10px', textAlign: 'center' }}>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {materials.map(m => (
                    <tr key={m.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                      <td style={{ padding: '12px 10px', fontWeight: 'bold', color: '#334155' }}>{m.title}</td>
                      <td style={{ padding: '12px 10px' }}>
                        <span style={{ padding: '3px 8px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold', backgroundColor: m.material_type === 'PDF' ? '#fee2e2' : '#e0f2fe', color: m.material_type === 'PDF' ? '#ef4444' : '#0ea5e9' }}>{m.material_type}</span>
                      </td>
                      <td style={{ padding: '12px 10px', color: '#475569' }}>{m.grade}</td>
                      <td style={{ padding: '12px 10px', color: '#64748b', fontSize: '12px' }}>{m.file_path}</td>
                      <td style={{ padding: '12px 10px', textAlign: 'center' }}>
                        <button onClick={() => handleDeleteMaterial(m.id)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                      </td>
                    </tr>
                  ))}
                  {materials.length === 0 && (
                    <tr><td colSpan="5" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8' }}>No materials published yet.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'forum':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>💬 Discussion Forum</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
                    <input type="text" placeholder="Share an announcement with your classes..." style={inputStyle} />
                    <button style={{ padding: '12px 30px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Post</button>
                </div>
                
                <h3 style={{ margin: '0 0 15px 0', color: '#1e293b', fontSize: '16px' }}>Student Questions</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{ padding: '20px', border: '1px solid #e2e8f0', borderRadius: '12px', backgroundColor: '#f8fafc' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                            <span style={{ fontWeight: 'bold', color: '#1e293b', fontSize: '14px' }}>Kasun Perera (Grade 10)</span>
                            <span style={{ fontSize: '12px', color: '#64748b' }}>2 hours ago</span>
                        </div>
                        <p style={{ margin: 0, color: '#475569', fontSize: '14px', lineHeight: '1.6' }}>Teacher, could you please upload the answers for the Term Test Revision Tute?</p>
                        <div style={{ marginTop: '15px', display: 'flex', gap: '10px' }}>
                            <input type="text" placeholder="Write a reply..." style={{...inputStyle, padding: '8px 12px', fontSize: '13px'}} />
                            <button style={{ padding: '8px 15px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' }}>Reply</button>
                        </div>
                    </div>
                </div>
            </div>
          </div>
        );

      case 'feedback':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>⭐ Student Feedback</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '25px' }}>View anonymous feedback submitted by your students to improve your teaching methods.</p>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{ padding: '20px', borderLeft: '5px solid #eab308', borderRadius: '8px', backgroundColor: '#fefce8', borderRight: '1px solid #fef08a', borderTop: '1px solid #fef08a', borderBottom: '1px solid #fef08a' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                            <h4 style={{ margin: '0 0 8px 0', color: '#854d0e', fontSize: '15px' }}>"Great Explanation!"</h4>
                            <span style={{ color: '#eab308', fontSize: '14px' }}>⭐⭐⭐⭐⭐</span>
                        </div>
                        <p style={{ margin: 0, fontSize: '13px', color: '#713f12', lineHeight: '1.5' }}>The video lesson you uploaded yesterday was very clear. Thank you!</p>
                        <div style={{ marginTop: '10px', fontSize: '12px', color: '#a16207', fontWeight: 'bold' }}>- Grade 10 Student</div>
                    </div>
                </div>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 My Profile & Security</h2>
            <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>
                        <h3 style={{ color: '#15803d', margin: 0 }}>Personal Details</h3>
                        {!isEditing ? <button onClick={() => setIsEditing(true)} style={editBtnStyle}>✏️ Edit Profile</button> : <button onClick={handleProfileUpdate} style={saveBtnStyle}>💾 Save</button>}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={labelStyle}>Full Name</label><input type="text" value={profileData.name} onChange={(e) => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Username (For Login)</label><input type="text" value={profileData.username} disabled style={{...inputStyleProfile(false), opacity: 0.8, backgroundColor: '#f1f5f9'}} /></div>
                        <div><label style={labelStyle}>Teaching Subject</label><input type="text" value={teachingSubject} disabled style={{...inputStyleProfile(false), opacity: 0.8, backgroundColor: '#f1f5f9'}} /></div>
                        <div><label style={labelStyle}>Qualifications</label><input type="text" value={profileData.qualifications} onChange={(e) => setProfileData({...profileData, qualifications: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Email Address</label><input type="email" value={profileData.email} onChange={(e) => setProfileData({...profileData, email: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Contact Number</label><input type="text" value={profileData.phone} onChange={(e) => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                    </div>
                </div>

                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#ef4444', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>🔑 Change Password</h3>
                    <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={labelStyle}>Current Password</label><input type="password" placeholder="Enter current password" style={inputStyle} /></div>
                        <div><label style={labelStyle}>New Password</label><input type="password" placeholder="Enter new password" style={inputStyle} /></div>
                        <div><label style={labelStyle}>Confirm New Password</label><input type="password" placeholder="Confirm new password" style={inputStyle} /></div>
                        <button type="button" style={{ width: '100%', padding: '12px', backgroundColor: '#1e293b', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', transition: '0.2s' }}>Update Password</button>
                    </form>
                </div>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px', letterSpacing: '1px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'forum'} onClick={() => setActiveTab('forum')} icon="💬" text="Student Forum" />
          <SidebarBtn active={activeTab === 'feedback'} onClick={() => setActiveTab('feedback')} icon="⭐" text="View Feedback" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
        </div>
        
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
            <button onClick={handleLogout} style={logoutBtnStyle}>🚪 Logout</button>
        </div>
      </div>
      
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

    </div>
  );
}

// Styles
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{count}</h2></div>
    <div style={{ width: '60px', height: '60px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>{icon}</div>
  </div>
);

